using Dalamud.Bindings.ImGui;
using Dalamud.Interface;
using GatherBuddy.Crafting;
using GatherBuddy.RebornUI.Settings;
using RebornMaterial;
using System;
using System.Numerics;

namespace GatherBuddy.Gui;

public partial class VulcanWindow
{
    private static readonly string[] SolverModeNames = ["Pure Raphael", "Standard Solver", "Progress Only"];

    private static readonly string[] SolverModeTooltips =
    [
        "Static rotations generated by the Raphael solver.\nConsistent, optimal results.",
        "A dynamic solver adapted from Artisan.\nReacts to conditions, more flexible.",
        "Completes crafts without quality actions.\nFastest execution, no quality output.",
    ];

    private static readonly VulcanSolverMode[] SolverModes = [VulcanSolverMode.PureRaphael, VulcanSolverMode.StandardSolver, VulcanSolverMode.ProgressOnly];

    private void DrawSettingsPage()
    {
        using (M3Card.Begin("vulcan_settings_crafting", "Crafting", FontAwesomeIcon.Hammer, M3.AccentFor(0)))
        {
            DrawSolverMode();
            SettingRows.Slider("Action delay", "Delay in milliseconds between crafting actions. 0 is instant, 1000 the most.",
                GatherBuddy.Config.VulcanExecutionDelayMs, 0, 1000, v => GatherBuddy.Config.VulcanExecutionDelayMs = v);
            SettingRows.Switch("Context menu entries",
                "Show Vulcan entries (Open in Vulcan, Add to Crafting List, Add to Vendor Buy List) in the in-game right-click menu.",
                GatherBuddy.Config.VulcanContextMenuEntries, v => GatherBuddy.Config.VulcanContextMenuEntries = v);
            SettingRows.Switch("Show recipe browser item tooltips", "Show the game's item tooltip when hovering recipe results on the Recipes page.",
                GatherBuddy.Config.ShowRecipeBrowserTooltips, v => GatherBuddy.Config.ShowRecipeBrowserTooltips = v);
            SettingRows.Hotkey("Hotkey to open recipes", "Opens Vulcan straight to the Recipes page.",
                GatherBuddy.Config.VulcanRecipesTabHotkey, v => GatherBuddy.Config.VulcanRecipesTabHotkey = v);
        }

        using (M3Card.Begin("vulcan_settings_repair", "Repair", FontAwesomeIcon.Wrench, M3.AccentFor(1)))
        {
            DrawVulcanRepairConfig();
        }

        using (M3Card.Begin("vulcan_settings_between", "Between crafts", FontAwesomeIcon.Gem, M3.AccentFor(2)))
        {
            var materia = GatherBuddy.Config.VulcanMateriaConfig;
            SettingRows.Switch("Enable materia extraction", "Extract materia from fully spiritbonded gear between crafts.",
                materia.Enabled, v => materia.Enabled = v);

            var retainerBell = GatherBuddy.Config.VulcanRetainerBellConfig;
            SettingRows.Switch("Auto-navigate to retainer bell", "Walk to the nearest retainer bell when starting a retainer restock.",
                retainerBell.AutoNavigateToRetainerBell, v => retainerBell.AutoNavigateToRetainerBell = v);
        }

        using (M3Card.Begin("vulcan_settings_raphael", "Raphael solver", FontAwesomeIcon.Brain, M3.AccentFor(3)))
        {
            DrawRaphaelConfig();
        }
    }

    private static void DrawSolverMode()
    {
        var raphaelConfig = GatherBuddy.Config.RaphaelSolverConfig;
        var index = Math.Max(0, Array.IndexOf(SolverModes, raphaelConfig.SolverMode));
        var width = MathF.Max(M3Widgets.ComboWidthFor(SolverModeNames[1]), 160f * M3.Scale);
        var row = M3SettingRow.Begin("Solver mode", "How Vulcan decides which crafting actions to use.", new Vector2(width, M3Widgets.ComboHeight));
        ImGui.SetCursorScreenPos(row.ControlPosition);
        var changed = M3Widgets.Combo("##vulcan_solver_mode", ref index, SolverModeNames.Length, i => SolverModeNames[i], width,
            itemTooltip: i => SolverModeTooltips[i]);
        M3SettingRow.End(row);

        if (!changed || index < 0 || index >= SolverModes.Length || SolverModes[index] == raphaelConfig.SolverMode)
        {
            return;
        }

        raphaelConfig.SolverMode = SolverModes[index];
        GatherBuddy.Config.Save();
        CraftingGameInterop.ReloadSolvers();
    }

    private static void DrawVulcanRepairConfig()
    {
        var config = GatherBuddy.Config.VulcanRepairConfig;
        SettingRows.Switch("Enable repair", "Repair your gear between crafts when needed.", config.Enabled, v => config.Enabled = v);
        SettingRows.Slider("Repair threshold", "Repair when the lowest gear condition drops below this percentage.",
            config.RepairThreshold, 0, 99, v => config.RepairThreshold = v);
        SettingRows.Switch("Prioritize NPC repair", "Use an NPC mender when one is available and you have enough gil; otherwise repair yourself.",
            config.PrioritizeNPCRepair, v => config.PrioritizeNPCRepair = v);

        if (!config.PrioritizeNPCRepair)
        {
            return;
        }

        using var sub = M3SubGroup.Begin();
        var npcs = RepairNPCHelper.RepairNPCs;
        var current = config.PreferredRepairNPC;
        var index = 0;
        if (current != null)
        {
            var found = npcs.FindIndex(n => n.DataId == current.DataId);
            index = found >= 0 ? found + 1 : 0;
        }

        var supporting = npcs.Count == 0
            ? "The list of menders is still loading."
            : "The mender to travel to when repairs are needed. Current Zone NPCs uses any mender nearby.";
        if (!M3Widgets.RowCombo("Preferred repair NPC", ref index, npcs.Count + 1,
                i => i == 0 ? "Current Zone NPCs" : $"{npcs[i - 1].Name} - {GetTerritoryName(npcs[i - 1].TerritoryType)}",
                supporting, search: true))
        {
            return;
        }

        if (index <= 0 || index > npcs.Count)
        {
            config.PreferredRepairNPC = null;
            config.PreferredRepairNPCDataId = 0;
        }
        else
        {
            var npc = npcs[index - 1];
            config.PreferredRepairNPC = npc;
            config.PreferredRepairNPCDataId = npc.DataId;
        }

        GatherBuddy.Config.Save();
    }

    private static void DrawRaphaelConfig()
    {
        var coordinator = GatherBuddy.RaphaelSolveCoordinator;
        var raphaelConfig = GatherBuddy.Config.RaphaelSolverConfig;

        SettingRows.Number("Max concurrent solves", "How many Raphael solves can run at the same time.",
            raphaelConfig.MaxConcurrentRaphaelProcesses, 1, 1000, v => raphaelConfig.MaxConcurrentRaphaelProcesses = v);
        SettingRows.Number("Solve timeout",
            "Minutes per Raphael solve. A solve that takes longer is marked as failed and the craft is skipped.",
            raphaelConfig.RaphaelTimeoutMinutes, 1, 60, v => raphaelConfig.RaphaelTimeoutMinutes = v, 1, "min");
        SettingRows.Number("Cache max age", "Solutions older than this are discarded when the plugin loads.",
            raphaelConfig.SolutionCacheMaxAgeDays, 1, 365, v => raphaelConfig.SolutionCacheMaxAgeDays = v, 1, "days");

        if (SettingRows.Switch("Backload progress",
                "Only use progress actions at the end of the rotation. May lower the quality you can reach; turn it off for the most quality. "
              + "Changing this clears the solution cache.",
                raphaelConfig.RaphaelBackloadProgress, v => raphaelConfig.RaphaelBackloadProgress = v))
        {
            coordinator.Clear();
        }

        if (SettingRows.Switch("Allow specialist actions",
                "When off (the default), Raphael makes non-specialist rotations even if you are a specialist. "
              + "Changing this clears the solution cache.",
                raphaelConfig.RaphaelAllowSpecialistActions, v => raphaelConfig.RaphaelAllowSpecialistActions = v))
        {
            coordinator.Clear();
        }

        M3Widgets.SectionLabel("Status");
        var muted = M3.Scheme.OnSurfaceVariant;
        M3Widgets.RowValue("Active solves", $"{coordinator.ActiveSolves} / {raphaelConfig.MaxConcurrentRaphaelProcesses}", null,
            coordinator.ActiveSolves > 0 ? M3.Severity(M3Severity.Success) : muted);
        M3Widgets.RowValue("Pending solves", coordinator.PendingSolves.ToString(), null,
            coordinator.PendingSolves > 0 ? M3.Severity(M3Severity.Warning) : muted);
        M3Widgets.RowValue("Cached solutions", coordinator.CachedSolutionCount.ToString(), null,
            coordinator.CachedSolutionCount > 0 ? M3.Severity(M3Severity.Success) : muted);

        if (M3Widgets.RowButton("Clear the solution cache", "Clear cache", "Deletes every saved Raphael solution.", M3ButtonStyle.Outlined,
                FontAwesomeIcon.Trash))
        {
            coordinator.Clear();
            M3Snackbar.Show("Cleared the Raphael solution cache.");
        }
    }
}
